/* Sinh tự động bởi build/make_lab.py – không sửa tay. Đáp án đã được băm. */
window.LABS=[{"id": 1, "buoi": 1, "title": "Danh mục tài sản và sổ rủi ro sau đợt thư lạ", "story": "Sáng 10/11/2026, Chánh Văn phòng Cơ quan Mẫu (giả lập) giao nhóm rà soát lại danh mục tài sản và lập sổ đăng ký rủi ro, vì ngày 05/11 nhiều cán bộ báo nhận được thư “mời họp khẩn Ban Thường vụ”. Nhóm được cấp danh mục tài sản cũ, danh sách nhân sự và nhật ký thư, DNS, proxy, netflow của 7 ngày (03–09/11).", "asks": ["Danh mục tài sản hiện có còn thiếu gì: chủ sở hữu, sao lưu, thiết bị chưa được kiểm kê?", "Thư “mời họp khẩn” đến từ đâu, bao nhiêu người nhận, đã có ai bấm hoặc nhập mật khẩu chưa?", "Bốn kịch bản rủi ro nào cần ưu tiên xử lý, ai chịu trách nhiệm, kiểm chứng bằng cách nào?"], "skill": "Lập danh mục tài sản từ hồ sơ và từ dữ liệu thực tế; viết kịch bản rủi ro đủ 4 thành phần; chấm L, I có luận cứ.", "steps": [{"t": "Vẽ ranh giới hệ thống", "w": "all", "d": "Mở trò chơi “Soi sơ đồ mạng”, tìm 6 điểm yếu. Ghi vào ô “Ranh giới hệ thống” trong công cụ cuối trang: những gì nằm trong ranh giới cơ quan, kết nối ra ngoài, dịch vụ phụ thuộc.", "go": ["Soi sơ đồ mạng", "#thuchanh-soimang"]}, {"t": "Lập danh mục tài sản (PL-01)", "w": "all", "d": "Mở kiem_ke_tai_san.csv. Tài sản nào để trống cột chủ sở hữu? Bao nhiêu tài sản ghi “Không” ở cột sao lưu? Chép vào bảng “Danh mục tài sản” của công cụ tối thiểu 6 tài sản, mỗi tài sản có chủ sở hữu, mức CIA, phụ thuộc, sao lưu.", "con": {"src": "kiem_ke_tai_san.csv", "view": "table"}, "cmd": "cd ~/lab/dulieu\ncolumn -s, -t < kiem_ke_tai_san.csv\ngrep -c ',Không$' kiem_ke_tai_san.csv"}, {"t": "Thiết bị công vụ và tệp dùng chung (VP)", "w": "vp", "d": "Làm “Soi phòng làm việc”: tìm nguy cơ với máy tính, điện thoại, USB, giấy tờ, tệp dùng chung. Đưa ít nhất 1 nguy cơ vào sổ rủi ro, mô tả tác động ở mức nghiệp vụ.", "go": ["Soi phòng làm việc", "#thuchanh-soiphong"]}, {"t": "Tìm thiết bị chưa được kiểm kê", "w": "it", "d": "Trong netflow.csv, đếm các địa chỉ đích thuộc vùng máy chủ 10.20.1.x. So với danh mục: địa chỉ nào có lưu lượng nhưng không có tên trong danh mục?", "con": {"src": "netflow.csv", "f": [["dich", "~", "10.20.1."]], "view": "group", "g": "dich"}, "cmd": "cd ~/lab/dulieu\nawk -F, 'NR>1 && $4 ~ /^10\\.20\\.1\\./ {print $4}' netflow.csv | sort | uniq -c | sort -rn"}, {"t": "Tìm thư giả mạo", "w": "all", "d": "Trong mail.log lọc các thư có spf=fail. Ghi lại tên miền người gửi, địa chỉ máy chủ gửi, tệp đính kèm và số hộp thư nhận. Cán bộ văn phòng làm thêm “Soi thư giả mạo” để so thư hợp lệ với thư giả.", "con": {"src": "mail.log", "f": [["spf", "=", "fail"]], "view": "table"}, "cmd": "cd ~/lab/dulieu\ngrep \"spf=fail\" mail.log\ngrep -c \"spf=fail\" mail.log"}, {"t": "Ai đã bấm, ai đã nhập mật khẩu?", "w": "it", "d": "Tìm tên miền của trang giả trong dns.log, rồi trong proxy.log tìm yêu cầu POST tới tên miền đó.", "con": {"src": "proxy.log", "q": "cqmau-xacthuc", "view": "table"}, "cmd": "cd ~/lab/dulieu\ngrep \"cqmau-xacthuc\" dns.log\ngrep \"cqmau-xacthuc\" proxy.log | grep POST"}, {"t": "Đối chiếu nhân sự", "w": "vp", "d": "Mở nhan_su.csv. Trong 7 người nhận thư giả có người đã nghỉ hưu nhưng tài khoản vẫn hoạt động. Đó là ai?", "con": {"src": "nhan_su.csv", "view": "table"}, "cmd": "cd ~/lab/dulieu\ngrep -i \"nghỉ hưu\" nhan_su.csv"}, {"t": "Lập sổ đăng ký rủi ro", "w": "all", "d": "Dùng công cụ bên dưới: tối thiểu 4 kịch bản, mỗi kịch bản có tài sản – nguồn đe dọa – điều kiện – hậu quả, L, I có luận cứ, biện pháp, người xử lý và cách kiểm chứng. Sắp theo R để ra thứ tự ưu tiên."}, {"t": "Phản biện chéo", "w": "all", "d": "Đổi sản phẩm với nhóm bên cạnh: kiểm tra mỗi kịch bản đủ 4 thành phần, luận cứ L/I có bằng chứng, có người chịu trách nhiệm. Ghi góp ý nhận được và nội dung nhóm đã sửa."}], "free": [["f1", "Nguy cơ với thiết bị công vụ, tệp dùng chung và cách báo khi phát hiện (VP)"], ["f2", "Phản biện chéo: nhóm bên cạnh góp ý gì? Nhóm sửa gì?"]], "tool": "riskreg", "program": "Bài thực hành 1 – Lập danh mục tài sản và sổ rủi ro. Bước 1: vẽ ranh giới hệ thống; bước 2: lập danh mục tài sản; bước 3: xác định kịch bản đe dọa và điểm yếu; bước 4: chấm khả năng/tác động và nêu luận cứ; bước 5: ưu tiên biện pháp, giao người xử lý; bước 6: phản biện chéo. Điểm R=L×I chỉ là quy ước giảng dạy, không phải công thức bắt buộc của NIST SP 800-30.", "vp": "Nhận diện nguy cơ email, thiết bị công vụ, tệp dùng chung; điền danh mục và đánh giá tác động ở mức nghiệp vụ.", "it": "Mô tả ranh giới mạng, phụ thuộc dịch vụ, quyền và sao lưu; bổ sung căn cứ cấu hình và kế hoạch kiểm soát.", "sanpham": "01 bảng tài sản, tối thiểu 04 kịch bản rủi ro và 01 Risk Register có mức ưu tiên, trách nhiệm và cách xác minh.", "tieuchi": "Kiểm tra mỗi kịch bản có tài sản–nguồn đe dọa–điều kiện–hậu quả, luận cứ chấm điểm và người chịu trách nhiệm.", "qs": [{"id": "q1", "l": "Tài sản nào trong danh mục chưa có chủ sở hữu?", "h": "ghi tên máy, ví dụ SRV-XXX", "t": "text", "w": "all", "k": ["d7ac1c01b4505cc62af4", "ef213d530359a72c1f79"]}, {"id": "q2", "l": "Số tài sản ghi “Không” ở cột sao lưu", "t": "num", "w": "all", "k": ["3b223ee8d620b654f517"]}, {"id": "q3", "l": "Địa chỉ vùng máy chủ có lưu lượng nhưng không có trong danh mục", "t": "text", "w": "it", "k": ["b4b4a915e876830b1d4a"]}, {"id": "q4", "l": "Tên miền người gửi thư giả mạo", "t": "text", "w": "all", "k": ["324bafee91648a93c46e", "cbc678a2c19dcdc8cc6e"]}, {"id": "q5", "l": "Số hộp thư nhận thư giả mạo", "t": "num", "w": "all", "k": ["7b0b013f0ee58d3c143b"]}, {"id": "q6", "l": "Tên tệp đính kèm", "t": "text", "w": "all", "k": ["1353aa9ab2891ec3d123"]}, {"id": "q7", "l": "Tài khoản đã nộp mật khẩu lên trang giả", "t": "text", "w": "it", "k": ["93b408c3f3a88424159b", "9928d51513e77859c487", "cd0c7aeffe20babca49d"]}, {"id": "q8", "l": "Tài khoản của người đã nghỉ hưu vẫn đang hoạt động", "t": "text", "w": "vp", "k": ["884ee3c42ae5047e45f1"]}]}, {"id": 2, "buoi": 2, "title": "Ma trận tuân thủ cho hệ thống văn bản có nhà thầu bảo trì", "story": "Hệ thống quản lý văn bản và điều hành (SRV-VB01) lưu thông tin cá nhân của cán bộ và do một nhà thầu bảo trì qua VPN. Lãnh đạo yêu cầu rà soát: hệ thống đang thiếu những bằng chứng tuân thủ nào theo các văn bản hiện hành? Nhóm được xem hồ sơ của hệ thống (10 tài liệu) và nhật ký tường lửa, đăng nhập 7 ngày.", "asks": ["Ai là chủ quản, đơn vị vận hành, bên xử lý dữ liệu?", "Mỗi nghĩa vụ đã có bằng chứng chưa: đủ, thiếu hay cần xác minh?", "Khoảng trống nào phải khắc phục trước, ai làm, hạn nào, kiểm tra lại thế nào?"], "skill": "Tra cứu căn cứ có hiệu lực; lập ma trận căn cứ – nghĩa vụ – bằng chứng – trạng thái; không kết luận pháp lý khi thiếu dữ liệu.", "steps": [{"t": "Xác định các bên", "w": "all", "d": "Đọc thẻ hồ sơ hệ thống trong công cụ bên dưới. Ghi: chủ quản hệ thống thông tin, đơn vị vận hành, bên xử lý dữ liệu (nhà thầu), chủ quản dữ liệu."}, {"t": "Tra cứu văn bản", "w": "all", "d": "Mở Sổ tra cứu hiệu lực. Với mỗi tài liệu trong hồ sơ, kiểm tra căn cứ ghi trong tài liệu còn hiệu lực không.", "go": ["Sổ tra cứu hiệu lực", "#phapluat"]}, {"t": "Kiểm tra truy cập của nhà thầu", "w": "it", "d": "Hợp đồng bảo trì hết hạn 30/06/2026. Trong fw.log, nhà thầu (198.51.100.200) còn kết nối không? Quy tắc nào cho phép?", "con": {"src": "fw.log", "f": [["src", "=", "198.51.100.200"]], "view": "table"}, "cmd": "cd ~/lab/dulieu\ngrep \"src=198.51.100.200\" fw.log | head\ngrep -c \"src=198.51.100.200\" fw.log\ngrep \"^9,\" fw_rules.csv"}, {"t": "Kiểm tra tài khoản người nghỉ hưu", "w": "it", "d": "Bảng phân quyền 15/09 còn tài khoản của người nghỉ hưu từ 01/10. Tài khoản đó có đăng nhập thành công (4624) trong 7 ngày qua không? Bao nhiêu lần?", "con": {"src": "windows_security.ndjson", "f": [["TargetUserName", "=", "vu.ngoc.lan"], ["EventID", "=", "4624"]], "view": "table"}, "cmd": "cd ~/lab/dulieu\njq -c 'select(.EventID==4624 and .TargetUserName==\"vu.ngoc.lan\")' windows_security.ndjson | wc -l"}, {"t": "Phân loại dữ liệu cá nhân và quy trình chia sẻ", "w": "vp", "d": "Làm trò chơi “Phân loại dữ liệu cá nhân”. Trường “tình trạng sức khoẻ” trong hồ sơ nghỉ phép thuộc loại nào? Sau đó mô tả quy trình chia sẻ dữ liệu cá nhân của hệ thống: chia sẻ cho ai, theo căn cứ nào, cần lưu bằng chứng gì.", "go": ["Phân loại dữ liệu cá nhân", "#thuchanh-dlcn"]}, {"t": "Ma trận vận hành (IT)", "w": "it", "d": "Từ hồ sơ E1–E10 và kết quả bước 3–4, lập ma trận: nhật ký (thu ở đâu, lưu bao lâu), tài khoản và phân quyền, cấu hình, cấp độ, sao lưu (đã thử khôi phục chưa), hợp đồng nhà cung cấp, đầu mối vận hành."}, {"t": "Lập ma trận tuân thủ", "w": "all", "d": "Trong công cụ bên dưới, chọn trạng thái Đủ / Thiếu / Cần xác minh cho 10 tài liệu, ghi nghĩa vụ, người phụ trách, hạn và cách kiểm tra lại. Bấm “Chấm trạng thái”."}], "free": [["f1", "Các bên và vai trò (sơ đồ chữ): chủ quản – đơn vị vận hành – bên xử lý – chủ quản dữ liệu – dữ liệu nào đi đâu"], ["f2", "Danh sách việc cần xử lý (việc – người – hạn – cách kiểm tra lại)"], ["f3", "Quy trình chia sẻ dữ liệu cá nhân và bằng chứng cần lưu (VP)"], ["f4", "Ma trận vận hành: nhật ký – tài khoản/phân quyền – cấu hình – cấp độ – sao lưu – hợp đồng – đầu mối (IT)"]], "tool": "compliance", "program": "Bài thực hành 2 – Rà soát một hệ thống yêu cầu nội bộ lưu dữ liệu cá nhân và có nhà cung cấp bảo trì: (1) liệt kê chủ quản, chủ vận hành, bên xử lý; (2) tra cứu văn bản; (3) xác định nghĩa vụ cần kiểm tra; (4) nêu bằng chứng còn thiếu; (5) lập kế hoạch khắc phục và tái kiểm tra.", "vp": "Phân loại dữ liệu cá nhân xử lý trong nghiệp vụ, quy trình chia sẻ và danh sách bằng chứng cần lưu.", "it": "Lập ma trận log, IAM, cấu hình, cấp độ, sao lưu, hợp đồng nhà cung cấp và đầu mối vận hành.", "sanpham": "01 ma trận căn cứ – nghĩa vụ – bằng chứng – trạng thái; 01 danh sách việc cần xử lý có trách nhiệm và hạn kiểm tra.", "tieuchi": "Căn cứ phải truy được nguồn; trạng thái phân biệt “đủ/thiếu/cần xác minh”; không đưa kết luận pháp lý khi thiếu dữ liệu.", "qs": [{"id": "q1", "l": "Số hiệu quy tắc tường lửa vẫn cho nhà thầu truy cập", "t": "num", "w": "it", "k": ["62465d43ceb46a5c3e92"]}, {"id": "q2", "l": "Số kết nối của nhà thầu trong 7 ngày (03–09/11)", "t": "num", "w": "it", "k": ["af4162fdf3fa4789f451"]}, {"id": "q3", "l": "Tài khoản phải thu hồi ngay", "t": "text", "w": "all", "k": ["501734700d0aa9e5c58c"]}, {"id": "q4", "l": "Số lần tài khoản đó đăng nhập thành công (4624) trong 7 ngày", "t": "num", "w": "it", "k": ["73de6e4c83a69d50c18e"]}, {"id": "q5", "l": "Số hiệu luật đã hết hiệu lực mà Quy chế ATTT của cơ quan còn ghi làm căn cứ", "h": "dạng xx/yyyy/QHxx", "t": "text", "w": "all", "k": ["621f89fc71a8e7fcdfa4", "b6edf52e6af221a553f2"]}, {"id": "q6", "l": "Số hiệu văn bản hiện hành quy định tiêu chí cấp độ", "t": "text", "w": "all", "k": ["066cbde34a49a1233ed8", "10381f1615f66384abf8", "930aa5533d58df669964"]}, {"id": "q7", "l": "Trường “tình trạng sức khoẻ” thuộc loại", "t": "sel", "o": ["Dữ liệu cá nhân cơ bản", "Dữ liệu cá nhân nhạy cảm", "Không phải dữ liệu cá nhân"], "w": "vp", "k": ["e46b9284b2298b5c85bc"]}]}, {"id": 3, "buoi": 3, "title": "Trinh sát được phép và đọc dấu vết trên cổng thông tin", "story": "Phần 1 (Ubuntu WSL trên máy của mình): nhóm IT chạy máy web giả lập, kiểm tra trạng thái, quan sát một yêu cầu HTTP hợp lệ và đọc kết quả Nmap ghi sẵn từ phòng lab máy ảo (máy Web 192.168.56.20). Phần 2 (dữ liệu): ngày 06/11 bộ phận CNTT thấy cổng thông tin chậm trong khoảng 20 phút buổi chiều. Nhóm phân tích web_access.log và suricata_eve.json để biết chuyện gì đã xảy ra và có gì bị lộ không.", "asks": ["Máy lab có những dịch vụ nào? Kết luận được gì, không kết luận được gì?", "Ai đã dò quét cổng thông tin, lúc nào, bao nhiêu yêu cầu?", "Yêu cầu nào là thử nghiệm bị chặn, yêu cầu nào thực sự trả về dữ liệu không nên lộ?"], "skill": "Phân biệt “phát hiện dịch vụ” với “chứng minh lỗ hổng”; phân biệt thử tấn công với khai thác thành công; không bị đánh lừa bởi nguồn truy cập nhiều nhất.", "steps": [{"t": "Xác nhận phạm vi và trạng thái ứng dụng (IT)", "w": "it", "d": "Trên Ubuntu WSL: chạy công cụ kiểm tra môi trường, khởi động máy web giả lập (chỉ nghe 127.0.0.1:3000 – chỉ chính máy mình truy cập được) và kiểm tra ứng dụng phản hồi HTTP 200. Phạm vi thử nghiệm duy nhất của phần này là 127.0.0.1. Phòng học có máy ảo: làm thêm Lab 8.", "cmd": "cd ~/lab\nbash congcu/kiem_tra_moi_truong.sh\npython3 congcu/may_web_gia_lap.py &\ncurl -sI http://127.0.0.1:3000/ | head -5", "web": {"kind": "curl", "m": "HEAD", "path": "/"}}, {"t": "Đọc kết quả Nmap", "w": "all", "d": "Mở nmap_192.168.56.20.txt (bản ghi sẵn). Cổng nào mở? Dịch vụ gì? Có kết luận được Juice Shop có lỗ hổng chỉ từ kết quả này không?", "con": {"src": "nmap_192.168.56.20.txt", "view": "raw"}, "cmd": "cd ~/lab/dulieu\ngrep -E \"^[0-9]+/tcp\" nmap_192.168.56.20.txt\ngrep \" open \" nmap_192.168.56.20.txt\n# Tuỳ chọn (đã cài nmap) – chỉ quét CHÍNH MÁY MÌNH, so với bản ghi sẵn:\nnmap -sV -p 22,80,443,3000 127.0.0.1"}, {"t": "Giải phẫu yêu cầu HTTP", "w": "all", "d": "Làm trò chơi “Giải phẫu HTTP” với tệp http_mau.txt. Nhớ làm sạch cookie/token trước khi đưa vào báo cáo.", "go": ["Giải phẫu HTTP", "#thuchanh-http"]}, {"t": "Quan sát một GET hợp lệ (IT)", "w": "it", "d": "Dùng curl -v gửi MỘT yêu cầu GET hợp lệ tới máy web giả lập. Ghi dòng yêu cầu, các tiêu đề, mã trạng thái; so với http_mau.txt. Nếu có cookie/token thì thay bằng “ĐÃ LÀM SẠCH”. Sau đó mở nhật ký của máy web giả lập: chính yêu cầu của nhóm hiện ra theo đúng định dạng web_access.log. Không gửi tải tấn công. (Có ZAP/Burp trên Windows: đặt proxy 127.0.0.1:8080 và làm tương tự.)", "cmd": "cd ~/lab/dulieu\ncurl -sv \"http://127.0.0.1:3000/rest/products/search?q=apple\" -o /dev/null 2>&1 | grep -E \"^(>|<)\"\ntail -n 3 ~/lab/ketqua/web_gia_lap_access.log\nawk '{print $9}' ~/lab/ketqua/web_gia_lap_access.log | sort | uniq -c", "web": {"kind": "curl", "m": "GET", "path": "/rest/products/search?q=apple"}}, {"t": "Thư, trang web đáng ngờ và cách báo cáo (VP)", "w": "vp", "d": "Làm “Soi trang đăng nhập giả”. Ghi các dấu hiệu nhận biết và các bước báo cáo: dừng lại – báo bộ phận CNTT kèm bằng chứng – không tự xoá – kiểm chứng qua kênh thứ hai. Cán bộ văn phòng không quét mạng.", "go": ["Soi trang đăng nhập giả", "#thuchanh-dangnhapgia"]}, {"t": "Ai truy cập nhiều nhất?", "w": "all", "d": "Đếm yêu cầu theo địa chỉ IP trong web_access.log. Địa chỉ đứng đầu là ai? Xem User-Agent trước khi kết luận.", "con": {"src": "web_access.log", "view": "group", "g": "ip"}, "cmd": "cd ~/lab/dulieu\nawk '{print $1}' web_access.log | sort | uniq -c | sort -rn | head"}, {"t": "Lọc theo mã lỗi 404", "w": "all", "d": "Chỉ giữ status = 404 rồi đếm theo IP. Địa chỉ nào dò quét?", "con": {"src": "web_access.log", "f": [["status", "=", "404"]], "view": "group", "g": "ip"}, "cmd": "cd ~/lab/dulieu\nawk '$9==404 {print $1}' web_access.log | sort | uniq -c | sort -rn | head"}, {"t": "Dòng thời gian của địa chỉ dò quét", "w": "it", "d": "Lọc theo IP đó, xem biểu đồ theo phút: bắt đầu, kết thúc lúc nào? Tổng bao nhiêu yêu cầu?", "con": {"src": "web_access.log", "f": [["ip", "=", "203.0.113.45"]], "view": "time", "b": "minute"}, "cmd": "cd ~/lab/dulieu\ngrep '^203.0.113.45 ' web_access.log | head -1\ngrep '^203.0.113.45 ' web_access.log | tail -1\ngrep -c '^203.0.113.45 ' web_access.log"}, {"t": "Thử hay thành công?", "w": "all", "d": "Với IP đó, đếm theo status. Yêu cầu nào trả 200? Yêu cầu nào 403? Yêu cầu nào 500? Ánh xạ sang OWASP Top 10:2025.", "con": {"src": "web_access.log", "f": [["ip", "=", "203.0.113.45"]], "view": "group", "g": "status"}, "cmd": "cd ~/lab/dulieu\ngrep '^203.0.113.45 ' web_access.log | awk '{print $9}' | sort | uniq -c\ngrep '^203.0.113.45 ' web_access.log | awk '$9==200 || $9==500'"}, {"t": "Đối chiếu cảnh báo IDS", "w": "it", "d": "Trong suricata_eve.json, lọc src_ip = 203.0.113.45. Các SID nào? Có khớp thời gian với nhật ký web không?", "con": {"src": "suricata_eve.json", "f": [["src_ip", "=", "203.0.113.45"]], "view": "group", "g": "alert.signature"}, "cmd": "cd ~/lab/dulieu\njq -r 'select(.src_ip==\"203.0.113.45\") | [.timestamp,.alert.signature_id,.alert.signature] | @tsv' suricata_eve.json"}, {"t": "Lập bảng ≥ 3 nguy cơ", "w": "all", "d": "Mỗi nguy cơ ghi: bằng chứng có thật – nhóm OWASP 2025 – kết luận có giới hạn (đã xác minh / giả thuyết) – biện pháp phòng thủ và nguồn log phát hiện."}], "free": [["f1", "Báo cáo dịch vụ trên lab (cổng – dịch vụ – độ tin cậy – điều KHÔNG kết luận được)"], ["f2", "Mẫu HTTP request/response đã làm sạch"], ["f3", "Bảng ≥ 3 nguy cơ: bằng chứng – OWASP – kết luận có giới hạn – phòng thủ – nguồn log"], ["f4", "Dấu hiệu thư/trang web đáng ngờ và quy trình báo cáo (VP)"]], "tool": null, "program": "Bài thực hành 3 – Trinh sát được phép và đọc dấu vết: (1) xác nhận host-only, snapshot; (2) kiểm tra trạng thái ứng dụng; (3) quét có giới hạn, lưu Nmap XML; (4) quan sát HTTP GET và header; (5) mô tả rủi ro OWASP 2025 dựa trên bằng chứng có thật; (6) đề xuất phòng thủ và telemetry.", "vp": "Đọc bản mô phỏng email/web đáng ngờ; xác định dấu hiệu và cách báo cáo, không trực tiếp quét mạng.", "it": "Chạy công cụ trên lab 192.168.56.0/24, phân tích kết quả quét và luồng HTTP; giữ nhật ký và bằng chứng.", "sanpham": "01 báo cáo dịch vụ trên lab, 01 mẫu HTTP request/response và 01 bảng ≥3 nguy cơ kèm kết luận có giới hạn.", "tieuchi": "Chỉ địa chỉ lab được dùng; biết giải thích “service detected ≠ vulnerable”; báo cáo không chứa token hoặc cookie thật.", "qs": [{"id": "q1", "l": "Các cổng ĐANG MỞ trên 192.168.56.20 (ghi theo thứ tự tăng dần, cách nhau dấu phẩy)", "t": "text", "w": "all", "k": ["550196bda0ae3a1e0d05", "ef9fcdd3ab9ced1715bc"]}, {"id": "q2", "l": "Có kết luận được ứng dụng ở cổng 3000 có lỗ hổng chỉ từ kết quả Nmap không?", "t": "sel", "o": ["Có", "Không"], "w": "all", "k": ["9065e23bd45782ee18e0"]}, {"id": "q3", "l": "IP gửi nhiều yêu cầu nhất (cả 7 ngày)", "t": "text", "w": "all", "k": ["9a5f7fecfc077814da9a"]}, {"id": "q4", "l": "IP đó là", "t": "sel", "o": ["Kẻ tấn công", "Bot tìm kiếm hợp lệ", "Máy nội bộ"], "w": "all", "k": ["bb5aea2c61bc076b5600"]}, {"id": "q5", "l": "IP dò quét cổng thông tin", "t": "text", "w": "all", "k": ["5b0526b36243cb50f671"]}, {"id": "q6", "l": "Tổng số yêu cầu của IP dò quét", "t": "num", "w": "it", "k": ["46af35351fdb4efd547d"]}, {"id": "q7", "l": "Đường dẫn bị lộ (trả về 200)", "t": "text", "w": "all", "k": ["3feca4c5d13fc7fc0ca5"]}, {"id": "q8", "l": "Số yêu cầu SQLi bị chặn (403)", "t": "num", "w": "it", "k": ["e636b65354d4d2e610dc"]}, {"id": "q9", "l": "Lỗi /.git/config thuộc nhóm OWASP Top 10:2025", "t": "sel", "o": ["A01 Kiểm soát truy cập", "A02 Cấu hình sai bảo mật", "A05 Chèn mã", "A10 Xử lý sai tình huống ngoại lệ"], "w": "all", "k": ["499f051abb6b833ef9c5"]}, {"id": "q10", "l": "Yêu cầu trả lỗi 500 kèm trang lỗi 18 KB gợi ý nhóm", "t": "sel", "o": ["A01 Kiểm soát truy cập", "A02 Cấu hình sai bảo mật", "A05 Chèn mã", "A10 Xử lý sai tình huống ngoại lệ"], "w": "it", "k": ["a674aa5fa819ff34a0d3"]}, {"id": "q11", "l": "Đã lỡ nhập mật khẩu vào trang đăng nhập giả, việc làm đầu tiên là", "t": "sel", "o": ["Báo ngay bộ phận CNTT và đổi mật khẩu từ một máy khác", "Xoá thư để không ai thấy", "Chờ xem có chuyện gì xảy ra không", "Chuyển tiếp thư cho đồng nghiệp hỏi ý kiến"], "w": "vp", "k": ["a650f7f536ae4c0be8ff"]}]}, {"id": 4, "buoi": 4, "title": "Xây dựng tuyến phát hiện: tường lửa → Suricata → Wazuh", "story": "Sáng thứ Hai 09/11, Wazuh hiển thị hàng trăm cảnh báo đăng nhập thất bại và hàng trăm cảnh báo Suricata trong tuần, nhưng hai ngày cuối tuần gần như im lặng. Trưởng phòng CNTT hỏi: trong đống cảnh báo đó, đâu là thật? Có ai đã vào được hệ thống không? Lối vào là gì và ai đã mở nó?", "asks": ["Quy tắc tường lửa nào cho phép RDP từ Internet, ai tạo, có phiếu thay đổi không? Quy tắc chặn có hoạt động không?", "Cảnh báo Suricata nào nhiều nhất – thật hay dương tính giả? Tuyến Suricata → Wazuh có thông suốt không?", "Nguồn dò mật khẩu thật là ai (đừng tin con số tổng)? Có đăng nhập thành công không, bằng tài khoản nào?"], "skill": "Đi theo đường dữ liệu sự kiện qua 3 tầng; phân biệt dương tính giả; đếm theo cửa sổ thời gian thay vì đếm tổng.", "steps": [{"t": "Đọc bộ quy tắc và hồ sơ thay đổi", "w": "all", "d": "So fw_rules.csv với ho_so_thay_doi.csv: quy tắc nào không có mã phiếu thay đổi?", "con": {"src": "fw_rules.csv", "view": "table"}, "cmd": "cd ~/lab/dulieu\ncolumn -s, -t fw_rules.csv\ncat ho_so_thay_doi.csv"}, {"t": "Ai đã đi qua quy tắc đó?", "w": "it", "d": "Lọc fw.log theo rule = 14. Các nguồn nào, vào lúc nào?", "con": {"src": "fw.log", "f": [["rule", "=", "14"]], "view": "table"}, "cmd": "cd ~/lab/dulieu\ngrep \"rule=14 \" fw.log"}, {"t": "Kiểm thử ALLOW/DENY", "w": "it", "d": "Đếm fw.log theo act (pass/block). Quy tắc chặn mặc định (rule 1) đã chặn bao nhiêu kết nối, vào những cổng nào? Đối chiếu với “Mô phỏng tường lửa”: gói tin được xét qua các quy tắc theo thứ tự nào?", "con": {"src": "fw.log", "f": [["rule", "=", "1"]], "view": "group", "g": "dport"}, "cmd": "cd ~/lab/dulieu\ngrep -o \"act=[a-z]*\" fw.log | sort | uniq -c\ngrep -c \"rule=1 act=block\" fw.log\ngrep \"rule=1 act=block\" fw.log | grep -o \"dport=[0-9]*\" | sort | uniq -c | sort -rn"}, {"t": "Cảnh báo Suricata nhiều nhất", "w": "all", "d": "Đếm theo alert.signature_id. SID đứng đầu do máy nào gây ra? Đó là tấn công hay dương tính giả?", "con": {"src": "suricata_eve.json", "view": "group", "g": "alert.signature_id"}, "cmd": "cd ~/lab/dulieu\njq -r '.alert.signature_id' suricata_eve.json | sort | uniq -c | sort -rn\njq -r 'select(.alert.signature_id==2100498) | .src_ip' suricata_eve.json | sort | uniq -c"}, {"t": "Cảnh báo RDP", "w": "it", "d": "Lọc dest_port = 3389. SID và thời điểm?", "con": {"src": "suricata_eve.json", "f": [["dest_port", "=", "3389"]], "view": "table"}, "cmd": "cd ~/lab/dulieu\njq -c 'select(.dest_port==3389)' suricata_eve.json"}, {"t": "Marker kiểm thử tuyến phát hiện", "w": "it", "d": "Trên Ubuntu WSL (đã cài suricata): tạo tệp bắt gói giả lập có 3 phiên HTTP, cho Suricata đọc tệp với quy tắc marker (congcu/marker.rules), kiểm tra eve.json có đúng một cảnh báo SID 1000001. Thử thêm: viết quy tắc thứ hai SID 1000002 bắt đường dẫn /rest/products/search rồi chạy lại. Trên dữ liệu: lọc alert.signature_id = 1000001 – có mấy lần, lúc nào, từ máy nào? Lần nào có phiếu thay đổi trong ho_so_thay_doi.csv?", "con": {"src": "suricata_eve.json", "f": [["alert.signature_id", "=", "1000001"]], "view": "table"}, "cmd": "cd ~/lab && mkdir -p ketqua/suricata\npython3 congcu/sinh_pcap.py ketqua/lab_marker.pcap\ncat congcu/marker.rules\nsuricata -r ketqua/lab_marker.pcap -S congcu/marker.rules -l ketqua/suricata -k none\njq -c 'select(.event_type==\"alert\") | {timestamp,src_ip,dest_ip,dest_port,sid:.alert.signature_id}' ketqua/suricata/eve.json\njq -r '.event_type' ketqua/suricata/eve.json | sort | uniq -c\n# Trên bộ dữ liệu:\ncd ~/lab/dulieu\njq -c 'select(.alert.signature_id==1000001) | {timestamp,src_ip,dest_ip}' suricata_eve.json\ngrep -i marker ho_so_thay_doi.csv", "web": {"kind": "suricata"}}, {"t": "Truy vết EVE JSON → Wazuh", "w": "it", "d": "Trong wazuh_alerts.ndjson lọc rule.id = 86601 (Suricata: Alert). Tìm sự kiện của cảnh báo RDP (SID 9000201): Wazuh ghi lúc nào? Đếm sự kiện 86601 theo ngày, so với số cảnh báo trong eve.json theo ngày: từ lúc nào Wazuh không còn nhận? Agent IDS01 còn hoạt động không (còn sự kiện 5501)? Đọc sự kiện quy tắc 591.", "con": {"src": "wazuh_alerts.ndjson", "f": [["rule.id", "=", "86601"]], "view": "time", "b": "day"}, "cmd": "cd ~/lab/dulieu\njq -r 'select(.rule.id==\"86601\") | .timestamp[0:10]' wazuh_alerts.ndjson | sort | uniq -c\njq -r '.timestamp[0:10]' suricata_eve.json | sort | uniq -c\njq -c 'select(.rule.id==\"86601\" and .data.alert.signature_id==9000201) | {timestamp,agent:.agent.name}' wazuh_alerts.ndjson\njq -c 'select(.agent.name==\"IDS01\" and .rule.id!=\"86601\" and .rule.id!=\"5501\")' wazuh_alerts.ndjson"}, {"t": "Bẫy đếm tổng", "w": "all", "d": "Trong windows_security.ndjson lọc EventID = 4625, đếm theo IpAddress. Địa chỉ đứng đầu là thiết bị gì (tra kiem_ke_tai_san.csv)?", "con": {"src": "windows_security.ndjson", "f": [["EventID", "=", "4625"]], "view": "group", "g": "IpAddress"}, "cmd": "cd ~/lab/dulieu\njq -r 'select(.EventID==4625) | .IpAddress' windows_security.ndjson | sort | uniq -c | sort -rn | head"}, {"t": "Đếm theo cửa sổ 1 phút", "w": "all", "d": "Vẫn lọc 4625, chuyển sang “Đếm theo cửa sổ thời gian”, cửa sổ phút, trường IpAddress. Bây giờ nguồn nào đứng đầu?", "con": {"src": "windows_security.ndjson", "f": [["EventID", "=", "4625"]], "view": "window", "g": "IpAddress", "b": "minute"}, "cmd": "cd ~/lab/dulieu\njq -r 'select(.EventID==4625) | \"\\(.TimeCreated[0:16]) \\(.IpAddress)\"' windows_security.ndjson | sort | uniq -c | sort -rn | head"}, {"t": "Có vào được không?", "w": "it", "d": "Lọc Computer = SRV-VB01 và bỏ EventID 4625. Có sự kiện 4624 từ 198.51.100.23 không? Tài khoản nào? LogonType? Sau đó có 4688, 4720, 4732 không? Đối chiếu Wazuh: agent SRV-VB01 có cảnh báo 60204 “Multiple Windows Logon Failures” lúc nào?", "con": {"src": "windows_security.ndjson", "f": [["Computer", "=", "SRV-VB01"], ["EventID", "!=", "4625"]], "view": "table"}, "cmd": "cd ~/lab/dulieu\njq -c 'select(.IpAddress==\"198.51.100.23\" and .EventID!=4625)' windows_security.ndjson\njq -c 'select(.EventID==4720 or .EventID==4732)' windows_security.ndjson"}, {"t": "MFA và quyền tối thiểu (VP)", "w": "vp", "d": "Làm “Rà soát ma trận phân quyền”: tìm 5 vi phạm (MFA, tài khoản dùng chung, quyền vượt nhu cầu, tài khoản người nghỉ hưu). Với mỗi vi phạm ghi biện pháp và người xử lý.", "go": ["Rà soát ma trận phân quyền", "#thuchanh-phanquyen"]}, {"t": "Đọc màn hình tổng quan cảnh báo (VP)", "w": "vp", "d": "Mở wazuh_alerts.ndjson, đếm theo rule.level rồi theo rule.description – tương tự màn hình tổng quan của Wazuh. Cảnh báo mức cao nhất là gì, trên máy nào? Theo quy trình báo sự kiện, ai cần được báo và báo những gì?", "con": {"src": "wazuh_alerts.ndjson", "view": "group", "g": "rule.level"}, "cmd": "cd ~/lab/dulieu\njq -r '.rule.level' wazuh_alerts.ndjson | sort -n | uniq -c\njq -c 'select(.rule.level>=10) | {timestamp,level:.rule.level,desc:.rule.description,agent:.agent.name}' wazuh_alerts.ndjson"}, {"t": "Lập phiếu sự kiện và ma trận tường lửa", "w": "all", "d": "Điền PL-04 cho sự kiện RDP (nguồn telemetry, tài sản, độ tin cậy, SEV sơ bộ, xử lý, người phụ trách, retest). Làm “Mô phỏng tường lửa” để ra ma trận quy tắc đúng (nguồn – đích – cổng – hành động – lý do).", "go": ["Mô phỏng tường lửa", "#thuchanh-tuonglua"]}, {"t": "Đưa môi trường về trạng thái ban đầu (IT)", "w": "it", "d": "Dừng máy web giả lập, xoá thư mục kết quả tạm, rồi chứng minh bộ dữ liệu gốc không bị thay đổi bằng mã băm SHA-512. Đây là bước tương đương “hoàn nguyên snapshot” của phòng lab máy ảo (làm thật ở Lab 8). Ghi kết quả vào phiếu.", "cmd": "cd ~/lab/dulieu\npkill -f may_web_gia_lap.py\nrm -rf ~/lab/ketqua\ncd ~/lab && sha512sum -c --quiet congcu/SHA512SUMS && echo 'Dữ liệu gốc nguyên vẹn'", "web": {"kind": "sha", "mode": "kiemtra"}}], "free": [["f1", "Ma trận firewall của nhóm (nguồn – đích – cổng – hành động – lý do)"], ["f2", "Phiếu sự kiện PL-04: ID/thời gian · nguồn telemetry · tài sản và dấu hiệu · độ tin cậy, SEV sơ bộ · xử lý, người quyết định · kết quả retest"], ["f3", "Đường đi nguồn log → cảnh báo: Suricata (SID, thời điểm) → Wazuh (sự kiện, thời điểm) – chỗ bị đứt và cách khắc phục (IT)"], ["f4", "Vi phạm MFA, phân quyền và biện pháp; người cần được báo theo quy trình báo sự kiện (VP)"], ["f5", "Kết quả đưa môi trường về trạng thái ban đầu và kiểm tra mã băm (IT); ở phòng lab máy ảo: kết quả hoàn nguyên snapshot"]], "tool": null, "program": "Bài thực hành 4 – Xây dựng tuyến phát hiện: (1) kiểm tra cấu hình mạng/firewall; (2) kích hoạt mẫu traffic hợp lệ và marker trong lab; (3) xác nhận Suricata ghi EVE JSON; (4) tra event tương ứng trên Wazuh; (5) xem log tài khoản; (6) lập phiếu cảnh báo và cách khắc phục; (7) hoàn nguyên snapshot.", "vp": "Thực hành kiểm tra MFA, quyền chia sẻ tệp, quy trình báo sự kiện và hiểu chức năng của dashboard qua màn hình mẫu.", "it": "Lập rule firewall và phân vùng; quan sát IDS; truy vết EVE JSON → Wazuh; xác thực Windows event 4625; kiểm tra quyền tối thiểu.", "sanpham": "01 ma trận firewall, 01 bản ghi Suricata có SID/timestamp, 01 kết quả tìm event Wazuh và 01 phiếu sự kiện.", "tieuchi": "Chỉ đánh giá có phát hiện khi có log đủ chuỗi thu thập; kiểm thử ALLOW/DENY, quyền IAM và kết quả hoàn nguyên.", "qs": [{"id": "q1", "l": "Số hiệu quy tắc cho phép RDP từ Internet", "t": "num", "w": "all", "k": ["6f152e8aeb22ab51819a"]}, {"id": "q2", "l": "Tài khoản đã tạo quy tắc đó", "t": "text", "w": "all", "k": ["f2e3f664ad726b916bcb"]}, {"id": "q3", "l": "Mã phiếu thay đổi của quy tắc đó", "t": "text", "w": "all", "k": ["3eda161da33732eda216", "67d2c576c4dd55ebad00", "8d3519b7d3ee42d106aa", "c9aa863efa86391da264", "f431e55141f149a16695"]}, {"id": "q4", "l": "SID xuất hiện nhiều nhất trong suricata_eve.json", "t": "num", "w": "all", "k": ["94f254c16965b9a222ff"]}, {"id": "q5", "l": "Cảnh báo đó là", "t": "sel", "o": ["Tấn công thật", "Dương tính giả từ máy giám sát nội bộ"], "w": "all", "k": ["d345ae44a6a7ff3ec234"]}, {"id": "q6", "l": "SID cảnh báo kết nối RDP từ Internet", "t": "num", "w": "it", "k": ["2ca4e8ab84eb607dd879"]}, {"id": "q7", "l": "Địa chỉ có nhiều 4625 nhất khi đếm TỔNG 7 ngày", "t": "text", "w": "all", "k": ["330afd42166819a54c81"]}, {"id": "q8", "l": "Địa chỉ có nhiều 4625 nhất trong MỘT phút", "t": "text", "w": "all", "k": ["12595c6738cfc2cfeb51"]}, {"id": "q9", "l": "Tổng số 4625 từ địa chỉ tấn công", "t": "num", "w": "it", "k": ["a35ebee945421f1c74e3"]}, {"id": "q10", "l": "Tài khoản đăng nhập thành công từ địa chỉ tấn công", "t": "text", "w": "all", "k": ["48428736ad5f6bfda6cd"]}, {"id": "q11", "l": "LogonType của lần đăng nhập đó", "t": "num", "w": "it", "k": ["4de03f3ddd50b3e8d4fa"]}, {"id": "q12", "l": "Tài khoản mới được tạo sau đó", "t": "text", "w": "it", "k": ["56890ce81858e047afe0"]}, {"id": "q13", "l": "Số kết nối bị quy tắc chặn mặc định (rule 1) chặn trong 7 ngày", "t": "num", "w": "it", "k": ["ced753f688f68eae2222"]}, {"id": "q14", "l": "Số lần marker SID 1000001 xuất hiện trong eve.json", "t": "num", "w": "it", "k": ["6ca0b44d5c5aea9ac72a"]}, {"id": "q15", "l": "Mã phiếu thay đổi của lần kiểm thử marker có kế hoạch", "t": "text", "w": "it", "k": ["444831160731a6c1e88f"]}, {"id": "q16", "l": "Wazuh ghi nhận cảnh báo RDP (SID 9000201) lúc (hh:mm:ss)", "t": "text", "w": "it", "k": ["345d1d0a07a9113a7907", "395274f07db10cf9635c"]}, {"id": "q17", "l": "Wazuh không còn nhận cảnh báo Suricata từ ngày nào?", "h": "dd/mm/yyyy", "t": "text", "w": "it", "k": ["378ebd172c26fbed053a", "3db3ffc9edcfce04ea64", "531f3e6b2d0f3218d8bf", "65a901fa0efe4babaa2e", "74c6b440b5de20ce24c3", "81cdfe0fb7c960aaf439", "85a7efc185a72cb1f9b2", "bb2148696780a76362b5", "f1150535ff7a7a5269fa"]}, {"id": "q18", "l": "Nguyên nhân hợp lý nhất khiến Wazuh ngừng nhận cảnh báo Suricata", "t": "sel", "o": ["Agent trên IDS01 không còn đọc được eve.json sau khi tệp được xoay vòng (localfile, quyền đọc) – agent vẫn hoạt động", "Cuối tuần không còn cảnh báo nào", "Suricata đã bị gỡ khỏi IDS01", "Wazuh tự xoá cảnh báo cũ"], "w": "all", "k": ["c72c93004e8726a0d123"]}, {"id": "q19", "l": "Tài khoản dùng chung “vanphong.chung” vi phạm nguyên tắc nào?", "t": "sel", "o": ["Không truy được trách nhiệm cá nhân, không áp được MFA cho từng người", "Không vi phạm vì chỉ có quyền chuyên viên", "Chỉ cần đổi mật khẩu định kỳ là đủ"], "w": "vp", "k": ["d938a834cb42706b9627"]}, {"id": "q20", "l": "Mô tả của cảnh báo có mức (rule.level) cao nhất trong tuần", "t": "text", "w": "vp", "k": ["24b59ae6b54f1bd8d56b", "b48de5b722b23587287e"]}]}, {"id": 5, "buoi": 5, "title": "Hồ sơ đề xuất cấp độ cho hệ thống văn bản điều hành (giả lập)", "story": "Hệ thống quản lý văn bản và điều hành của Cơ quan Mẫu (giả lập) phục vụ khoảng 30 cán bộ trong cơ quan; xử lý văn bản thường, thông tin riêng của cơ quan và thông tin cá nhân của cán bộ. Văn bản mật xử lý trên mạng riêng, KHÔNG qua hệ thống này. Hệ thống không cung cấp dịch vụ cho người dân. Thành phần: reverse proxy, web, API, cơ sở dữ liệu, tệp đính kèm lưu trên SRV-FILE01, xác thực qua AD dùng chung, sao lưu về SRV-BK01, nhà thầu bảo trì qua VPN. Nhóm lập bộ hồ sơ minh hoạ HS-01…HS-06.", "asks": ["Ranh giới hệ thống gồm những gì, phụ thuộc vào gì, trust boundary ở đâu?", "Loại thông tin, đối tượng phục vụ, tác động CIA khi bị lộ/sửa/gián đoạn?", "Cấp độ đề xuất (tham chiếu) và căn cứ; biện pháp và bằng chứng còn thiếu?"], "skill": "Mô tả ranh giới và luồng dữ liệu; lập luận cấp độ theo tiêu chí; truy vết biện pháp – bằng chứng; không tự gán cấp độ.", "steps": [{"t": "Ghi thông tin hệ thống (HS-01)", "w": "all", "d": "Điền phần Tổng quan trong công cụ bên dưới: tên, mục tiêu, chủ quản, đơn vị vận hành, người dùng, loại dữ liệu."}, {"t": "Vẽ as-is và trust boundary (HS-02)", "w": "it", "d": "Đánh dấu trên sơ đồ: thành phần THUỘC hệ thống và thành phần PHỤ THUỘC; các điểm trust boundary.", "go": ["Xem sơ đồ kiến trúc (Chuyên đề 5)", "#chuyende-5"]}, {"t": "Đối chiếu dữ liệu thực tế", "w": "it", "d": "Tra kiem_ke_tai_san.csv: thành phần nào trong ranh giới chưa có sao lưu? Chưa có chủ?", "con": {"src": "kiem_ke_tai_san.csv", "view": "table"}, "cmd": "cd ~/lab/dulieu\ngrep -E 'SRV-VB01|SRV-FILE01|SRV-BK01|SRV-DC01' kiem_ke_tai_san.csv"}, {"t": "Tác động CIA và đề xuất cấp độ (HS-03)", "w": "all", "d": "Mô tả hậu quả nghiệp vụ khi lộ / sửa / gián đoạn. Dùng trình hỗ trợ lập luận cấp độ; ghi điều khoản cần đối chiếu."}, {"t": "Phương án bảo vệ (HS-04, HS-05)", "w": "it", "d": "Ma trận yêu cầu – biện pháp – bằng chứng: xác thực, phân quyền, nhật ký, sao lưu, quản lý thay đổi, nhà thầu."}, {"t": "Rà soát chéo (HS-06)", "w": "all", "d": "Đổi hồ sơ với nhóm bên cạnh, ghi danh sách tồn tại và hướng khắc phục."}], "free": [["f1", "Ghi chú điều khoản đã đối chiếu (số Điều/khoản, nguồn, ngày tra)"]], "tool": "dossier", "program": "Bài thực hành 5 – Hồ sơ cấp độ cho hệ thống văn bản điều hành giả lập: (1) ghi thông tin hệ thống; (2) vẽ as-is và trust boundary; (3) phân tích tài sản và tác động CIA; (4) đối chiếu tiêu chí và ghi căn cứ; (5) viết phương án quản lý/kỹ thuật; (6) rà soát chéo và ghi danh sách tồn tại. Bản thực hành không phải hồ sơ phê duyệt chính thức.", "vp": "Mô tả quy trình nghiệp vụ, loại dữ liệu, người dùng và ảnh hưởng khi gián đoạn/lộ/sửa dữ liệu.", "it": "Mô tả sơ đồ mạng, trust boundary, IAM, log, sao lưu, quản trị thay đổi và biện pháp kỹ thuật, kèm bằng chứng.", "sanpham": "Bộ hồ sơ giả lập có tổng quan, sơ đồ as-is, thuyết minh căn cứ, phương án bảo vệ và checklist hoàn thiện.", "tieuchi": "Đánh giá dựa vào ranh giới, luận cứ CIA, đối chiếu tiêu chí và truy vết biện pháp–bằng chứng; không tự gán cấp độ.", "qs": [{"id": "q1", "l": "Loại thông tin hệ thống xử lý", "t": "sel", "o": ["Chỉ thông tin công cộng", "Thông tin riêng và thông tin cá nhân, không có bí mật nhà nước", "Có bí mật nhà nước"], "w": "all", "k": ["cfde8cdb135e678e5354"]}, {"id": "q2", "l": "Đối tượng phục vụ", "t": "sel", "o": ["Nội bộ cơ quan", "Người dân, doanh nghiệp", "Liên ngành, toàn quốc"], "w": "all", "k": ["54200418a9f4400b59ea"]}, {"id": "q3", "l": "Cấp độ đề xuất THAM CHIẾU theo tóm tắt Điều 11–12 NĐ 331/2026", "t": "sel", "o": ["1", "2", "3", "4", "5"], "w": "all", "k": ["ab0b3cdc6b3304d01183"]}, {"id": "q4", "l": "Thành phần trong ranh giới hệ thống nhưng danh mục ghi “không sao lưu”", "t": "text", "w": "it", "k": ["b317e81f8e2ad3539e3c"]}, {"id": "q5", "l": "Với cấp độ đề xuất đó, ai thẩm định và phê duyệt (tóm tắt Điều 18)?", "t": "sel", "o": ["Đơn vị chuyên trách an ninh mạng của chủ quản", "Bộ Công an", "Nhà thầu bảo trì", "UBND tỉnh"], "w": "all", "k": ["87112938bfe630354477"]}, {"id": "q6", "l": "Điều 39 NĐ 331: hệ thống đang đầu tư trước 01/7/2026 phải hoàn thành thẩm định, phê duyệt cấp độ trong bao nhiêu tháng?", "t": "num", "w": "all", "k": ["0bf08f4528597c12462e"]}]}, {"id": 6, "buoi": 6, "title": "Diễn tập tabletop: sự cố sáng thứ Bảy 07/11", "story": "09:45 thứ Bảy 07/11/2026, Wazuh báo “The audit log was cleared” trên SRV-VB01. Đội ứng cứu được triệu tập. Nhóm có toàn bộ log 7 ngày. Nhiệm vụ: dựng dòng thời gian, tách dữ kiện và giả thuyết, xác định mức SEV, đề xuất ngăn chặn có người phê duyệt, khôi phục và lập báo cáo sau sự cố.", "asks": ["Chuyện gì đã xảy ra, theo thứ tự nào, dựa trên bằng chứng nào?", "Cảnh báo Suricata 09:20 có thuộc chuỗi tấn công không?", "Mức SEV nào, ai phê duyệt ngăn chặn, khôi phục và kiểm tra lại thế nào?"], "skill": "Tương quan nhiều nguồn log theo máy, tài khoản, thời gian; tách dữ kiện/giả thuyết; ra quyết định có thẩm quyền; lập báo cáo sau sự cố.", "steps": [{"t": "Phân vai", "w": "all", "d": "Trong công cụ bên dưới, giao vai: Chỉ huy (IR), Phân tích (SOC), Kỹ thuật (IT), Pháp chế, Chủ hệ thống, Thư ký. Cán bộ văn phòng nhận vai người phát hiện, chủ hệ thống, đầu mối báo cáo."}, {"t": "Chuỗi trên Windows", "w": "it", "d": "Lọc Computer = SRV-VB01, bỏ 4625. Đọc 4624, 4688, 4720, 4732, 1102.", "con": {"src": "windows_security.ndjson", "f": [["Computer", "=", "SRV-VB01"], ["EventID", "!=", "4625"]], "view": "table"}, "cmd": "cd ~/lab/dulieu\njq -c 'select(.Computer==\"SRV-VB01\" and .EventID!=4625)' windows_security.ndjson"}, {"t": "Thay đổi tệp (Wazuh FIM)", "w": "it", "d": "Lọc agent.name = SRV-VB01 và chỉ giữ sự kiện giám sát toàn vẹn tệp (có trường syscheck.path). Bao nhiêu tệp bị sửa, thư mục nào, tệp nào mới xuất hiện?", "con": {"src": "wazuh_alerts.ndjson", "f": [["agent.name", "=", "SRV-VB01"], ["syscheck.path", "!=", ""]], "view": "table"}, "cmd": "cd ~/lab/dulieu\njq -c 'select(.agent.name==\"SRV-VB01\" and .syscheck != null) | {timestamp,rule:.rule.id,path:.syscheck.path,event:.syscheck.event}' wazuh_alerts.ndjson"}, {"t": "Cảnh báo 09:20", "w": "all", "d": "Lọc suricata_eve.json theo thời gian 07/11 09:1x–09:2x. Cảnh báo 09:20 đến từ máy nào? Có liên quan SRV-VB01 không?", "con": {"src": "suricata_eve.json", "q": "2026-11-07T09:", "view": "table"}, "cmd": "cd ~/lab/dulieu\ngrep '2026-11-07T09:' suricata_eve.json | jq -c '{timestamp,src_ip,dest_ip,sid:.alert.signature_id,sig:.alert.signature}'"}, {"t": "Dữ liệu có bị gửi ra ngoài?", "w": "it", "d": "Trong netflow.csv dùng “Tổng theo trường”: tổng byte_di theo dich. Đích lớn nhất là gì? Lọc bỏ đích nội bộ (10.) thì đích nào lộ ra?", "con": {"src": "netflow.csv", "f": [["nguon", "=", "10.20.1.21"], ["dich", "!~", "10."]], "view": "sum", "g": "dich", "sf": "byte_di"}, "cmd": "cd ~/lab/dulieu\nawk -F, 'NR>1 {s[$4]+=$9} END {for (d in s) printf \"%d MB %s\\n\", s[d]/1048576, d}' netflow.csv | sort -rn | head\nawk -F, 'NR>1 && $3==\"10.20.1.21\" && $4==\"203.0.113.77\" {s+=$9} END {printf \"%d MB\\n\", s/1048576}' netflow.csv"}, {"t": "Thống nhất dòng thời gian", "w": "all", "d": "Kéo các sự kiện vào dòng thời gian, đánh dấu Dữ kiện / Giả thuyết, ghi nguồn. Làm thêm “Dựng dòng thời gian từ 4 nguồn log”.", "go": ["Dựng dòng thời gian", "#thuchanh-timeline"]}, {"t": "SEV, ngăn chặn, khôi phục", "w": "all", "d": "Chọn SEV có căn cứ; với từng quyết định ngăn chặn ghi người phê duyệt và rủi ro; nêu cách loại bỏ, khôi phục, theo dõi, retest. Có thể chơi “60 phút đầu tiên” trước.", "go": ["60 phút đầu tiên", "#thuchanh-sucoso"]}, {"t": "Bảo toàn bằng chứng (IT)", "w": "it", "d": "Tính SHA-256 các tệp nhật ký dùng làm bằng chứng; ghi phiếu chuỗi bàn giao: tệp – mã băm – người thu – thời điểm – nơi lưu. Phân tích trên bản sao, không sửa bản gốc.", "cmd": "cd ~/lab/dulieu && mkdir -p ~/lab/ketqua\nsha256sum windows_security.ndjson wazuh_alerts.ndjson suricata_eve.json netflow.csv | tee ~/lab/ketqua/bang_chung.sha256\nsha256sum -c ~/lab/ketqua/bang_chung.sha256", "web": {"kind": "sha"}}, {"t": "Báo cáo sau sự cố", "w": "all", "d": "Bấm “Tạo báo cáo” trong công cụ: mã sự cố; phạm vi, tài sản; dòng thời gian; bằng chứng và nơi lưu; SEV và người phê duyệt; quyết định containment; khắc phục, khôi phục, retest; kết luận và cải tiến."}, {"t": "Kiểm tra cuối khoá", "w": "all", "d": "Sau khi nộp báo cáo, mỗi học viên làm bài kiểm tra cuối khoá 20 câu (15 phút) và nhận giấy xác nhận hoàn thành.", "go": ["Kiểm tra cuối khoá", "#kiemtra"]}], "free": [["f1", "Quyết định ngăn chặn (việc – người phê duyệt – rủi ro – thời điểm)"], ["f2", "Khắc phục, khôi phục, theo dõi, retest"], ["f3", "Bài học và biện pháp cải tiến"], ["f4", "Phiếu chuỗi bàn giao bằng chứng: tệp – SHA-256 – người thu – thời điểm – nơi lưu (IT)"]], "tool": "tabletop", "program": "Bài thực hành 6 – Diễn tập tabletop: (1) phân vai IR/SOC/IT/pháp chế/chủ hệ thống; (2) đọc log và thống nhất timeline; (3) xác định mức SEV kèm căn cứ; (4) chọn phương án containment và người phê duyệt; (5) đề xuất loại bỏ, khôi phục và theo dõi; (6) lập báo cáo sự cố và bài học. Không tác động vào hệ thống thật.", "vp": "Đóng vai người phát hiện, chủ hệ thống, đầu mối báo cáo; ghi nhận diễn biến và quyết định theo kịch bản.", "it": "Tương quan EVE JSON, Windows events, Wazuh FIM; phân tích false positive, chain of custody, kế hoạch cô lập và khôi phục.", "sanpham": "01 timeline, 01 phiếu phân loại SEV và quyết định xử lý, 01 báo cáo sau sự cố cùng phiếu kiểm tra cuối khóa.", "tieuchi": "Ghi tách dữ kiện/giả thuyết, mức độ có luận cứ, quyết định có thẩm quyền, bằng chứng có thời gian và hành động cải tiến.", "qs": [{"id": "q1", "l": "Đăng nhập thành công của kẻ tấn công lúc (hh:mm:ss)", "t": "text", "w": "all", "k": ["a6d5d793e3aca3d1c5ab", "e4dbed80641432a35ae2"]}, {"id": "q2", "l": "Số tệp bị thay đổi theo FIM", "t": "num", "w": "it", "k": ["07be65215d0d5439884a"]}, {"id": "q3", "l": "Tên tệp thực thi mới xuất hiện", "t": "text", "w": "it", "k": ["3753b68c399db97cc041", "9444ca980d58d17add88"]}, {"id": "q4", "l": "Địa chỉ nguồn của cảnh báo Suricata lúc 09:20", "t": "text", "w": "all", "k": ["a2a92005a25f32d16058"]}, {"id": "q5", "l": "Cảnh báo 09:20 có thuộc chuỗi tấn công SRV-VB01 không?", "t": "sel", "o": ["Có – cùng thời điểm nên cùng chuỗi", "Chưa đủ căn cứ – khác máy nguồn, nhiều khả năng là marker kiểm thử, cần xác minh"], "w": "all", "k": ["742019ad60684f42d7ba"]}, {"id": "q6", "l": "Địa chỉ Internet nhận dữ liệu từ SRV-VB01", "t": "text", "w": "it", "k": ["003d7e831c625d1fb0b0"]}, {"id": "q7", "l": "Tổng dữ liệu gửi tới địa chỉ đó (MB, làm tròn)", "h": "chấp nhận sai số ±2%", "t": "num", "w": "it", "k": ["05c742c53683c8376e33", "0ce3713adc32503f2c9c", "131e640ddb9559114a0f", "1512260bff83a5e2eadd", "1531ab82966be4b5aea9", "156cac5280f578590955", "169a6e65c0a8eb376f1a", "20c3553eda49366d911e", "23765ba26fb259b30043", "3522babaebaee0be7142", "36be22865399c925ecd8", "379ca6e6af88eb0cc5d6", "3966e49dc34741c1bbc3", "3f8deddb3e4a9a932d86", "4013ed346b5575845c00", "40c06df3a664636660fd", "4558a813bd9258ba2d5d", "4569ceed75e81f36293f", "47e790562b8bbe0579db", "48200a68592a8c96861c", "4a17496e82f9f0a282ca", "4cec678d8db48281bcf5", "55397c716c2dd1671b68", "56e4ae05c69fe4494096", "57ebf1c21f80f9f32d1f", "5b14901a38259f15f5f4", "5d854c08f03285dc6c3a", "5ec5aa589e6f59493f1c", "63c7326d8ab9dee84a10", "64d60fd3d5034b856a60", "6637971214c3deb372de", "6b711ceb1b8e1e57f640", "6e91072d29cbc1be4eaf", "701a5b218ac5ecc539f8", "72efe8192c363113dc8e", "7334a43bfedd5f63a6e2", "768687dda99774afb97a", "7e9001178b1ae0468147", "7f9e567434a38b2bb68d", "7fa9bf4cf42d9c1031ef", "82900e90368bffa43d98", "829f560fc7c5c853753c", "869ce67954a6c4068581", "877430af82c1ac03ca9e", "87d5607d1f6896277f7f", "88e424c33f124719dbfb", "8a5bb65d897b70f2b239", "8af9c79945dc04bdbf2e", "8b2676b98466910ea4fa", "962778b580e2c7bc78eb", "98e1b5f461d413b41874", "9991c20f0b2df4eb62d3", "a20b473e37d6f6ba60ee", "a91739311c34d2b89502", "ab75bb7f9cd53e2fd580", "af79449a36a6c7b93e8d", "b13777c360305d5da224", "b13aadd769d8119870df", "b3492507eab7d9471bc6", "b8594167eeae542b6a26", "b9daba594621336685eb", "ba3fce7de1916fa0a8c9", "bb1aa55e62078689b928", "bc6840ba23420565aa75", "c198b53e87d49235604a", "c4f078333032a7c36d77", "c552709e85d7d980879c", "c6adee697841d9722c9b", "d74c99ff2832336a0f8e", "d87becf135fb241a4dc5", "dafaa7814ea5c3002516", "ddd7a572a2550338f508", "df38f6cb78f158117f8f", "e2865acc86f3baad8854", "e66151b225d5feda0669", "e8d633025ad44dca0275", "e8e0a0a6cf90905a602e", "e9a965bad4f65b4a0e63", "ec5899f547572a9c59c6", "f2aa559ffc35aa616949", "f658f1bc794284eee3c3", "fd231fdd3b5f93bc79fc", "ff19b3c51a99a47d3a03"]}, {"id": "q8", "l": "Nhật ký bảo mật bị xoá lúc (hh:mm:ss)", "t": "text", "w": "all", "k": ["239b07ea3bcb940e0802", "446e452f7edf6e8e6d5c"]}, {"id": "q9", "l": "Mức SEV đề xuất (theo thang của khoá học)", "t": "sel", "o": ["SEV-1", "SEV-2", "SEV-3", "SEV-4"], "w": "all", "k": ["f79fcd009f0b5cd6c1ec"]}, {"id": "q10", "l": "12 ký tự đầu của mã SHA-256 tệp windows_security.ndjson", "t": "text", "w": "it", "k": ["1d0f8a4e0661f2e730ff"]}]}, {"id": 7, "buoi": 0, "ext": true, "title": "AI phát hiện thư lừa đảo: huấn luyện, đánh giá và giới hạn", "story": "Sau đợt thư “mời họp khẩn” ngày 05/11, Phòng CNTT Cơ quan Mẫu (giả lập) đề xuất thử một bộ lọc thư dùng trí tuệ nhân tạo. Trước khi trình lãnh đạo, nhóm được giao: dùng 600 thư đã gán nhãn (đã trích thành các đặc trưng có/không, không chứa nội dung thư thật) để huấn luyện một mô hình nhỏ; đo xem mô hình chặn đúng, chặn nhầm, để lọt bao nhiêu thư; rồi thử với kiểu thư lừa đảo mới để biết giới hạn của nó.", "asks": ["Dấu hiệu nào giúp phân biệt thư lừa đảo – và dấu hiệu nào không đáng tin như ta tưởng?", "Mô hình tốt đến đâu so với một quy tắc đơn giản? Đánh đổi giữa chặn nhầm và để lọt là gì, nên chọn ngưỡng nào?", "Khi kẻ gian đổi cách viết, mô hình còn hiệu quả không? Cần thêm biện pháp gì ngoài AI?"], "skill": "Hiểu quy trình dữ liệu → đặc trưng → huấn luyện → đánh giá; đọc ma trận nhầm lẫn, độ chuẩn xác, độ phủ; chọn ngưỡng theo mục đích sử dụng; nhận biết giới hạn của mô hình và yêu cầu về dữ liệu cá nhân khi dùng AI.", "program": "Lab mở rộng, không nằm trong lịch 6 buổi 240 phút. Dùng khi nhóm làm xong sớm (sau Lab 1 hoặc Lab 6) hoặc tự học sau khoá; thời lượng gợi ý 45–60 phút. Cán bộ văn phòng làm trên công cụ web; cán bộ IT làm thêm bằng script congcu/ai_phishing.py.", "vp": "Đọc dữ liệu, huấn luyện trên công cụ web, đọc ma trận nhầm lẫn, chọn ngưỡng và rút ra kết luận về cách dùng AI an toàn.", "it": "Làm như nhánh văn phòng, sau đó chạy lại bằng Python, đối chiếu kết quả, thử bỏ/thêm đặc trưng và đề xuất cách tích hợp vào cổng lọc thư.", "sanpham": "Phiếu ghi nhận có kết quả mô hình (đặc trưng, trọng số, ma trận nhầm lẫn ở hai tập), ngưỡng đề xuất kèm lý do, và đề xuất biện pháp ngoài AI.", "tieuchi": "Đọc đúng các con số; giải thích được đánh đổi chặn nhầm – để lọt; không kết luận “AI thay thế được quy trình”; nêu đúng điều kiện khi dùng dữ liệu thư thật.", "steps": [{"t": "Nhìn bộ dữ liệu", "w": "all", "d": "Mở thu_huan_luyen.csv, đếm theo trường nhan. Có bao nhiêu thư lừa đảo, bao nhiêu thư hợp lệ? Mỗi dòng là một thư đã được trích thành đặc trưng.", "con": {"src": "thu_huan_luyen.csv", "view": "group", "g": "nhan"}, "cmd": "cd ~/lab/dulieu\nawk -F, 'NR>1 {print $NF}' thu_huan_luyen.csv | sort | uniq -c"}, {"t": "SPF có đủ để bắt thư lừa đảo?", "w": "all", "d": "Chỉ giữ nhan = lừa đảo, đếm theo spf. Bao nhiêu thư lừa đảo vẫn có SPF = pass? Vì sao kẻ gian vẫn qua được SPF?", "con": {"src": "thu_huan_luyen.csv", "f": [["nhan", "=", "lừa đảo"]], "view": "group", "g": "spf"}, "cmd": "cd ~/lab/dulieu\nawk -F, 'NR>1 && $NF==\"lừa đảo\" {print $8}' thu_huan_luyen.csv | sort | uniq -c"}, {"t": "So sánh dấu hiệu, chọn đặc trưng", "w": "all", "d": "Trong công cụ bên dưới, phần A: so tỉ lệ từng dấu hiệu ở thư lừa đảo và thư hợp lệ. Phần B: chọn 10 đặc trưng cơ bản, bấm “Huấn luyện mô hình”. Đặc trưng nào có trọng số lớn nhất?"}, {"t": "Đánh giá ở ngưỡng 0,50", "w": "all", "d": "Phần C, Tập kiểm tra, ngưỡng 0,50: đọc ma trận nhầm lẫn (chặn đúng, lọt lưới, chặn nhầm, cho qua đúng). So sánh với quy tắc “chặn khi SPF không đạt”."}, {"t": "Chọn ngưỡng theo mục đích", "w": "all", "d": "Kéo ngưỡng từ 0,30 đến 0,90, xem đường đánh đổi. Đề xuất một ngưỡng cho việc CHẶN HẲN và một ngưỡng cho việc GẮN NHÃN CẢNH BÁO, có lý do."}, {"t": "Kẻ gian đổi cách viết", "w": "all", "d": "Chuyển sang Tập “né tránh”, ngưỡng 0,50. Mô hình bắt được bao nhiêu trong 40 thư lừa đảo? Đọc bảng thư bị lọt: các thư này giống thư hợp lệ ở điểm nào?"}, {"t": "Vòng 2: thêm tín hiệu mới", "w": "all", "d": "Bấm “Vòng 2: mở khoá đặc trưng mới”, chọn thêm “Yêu cầu nhạy cảm”, huấn luyện lại. Đánh giá lại Tập né tránh ở ngưỡng 0,50 và 0,30."}, {"t": "Làm lại bằng Python (IT)", "w": "it", "d": "Chạy script trên Ubuntu WSL (thư mục ~/lab), đối chiếu kết quả với công cụ web – hai bên phải ra cùng con số. Thử bỏ từng đặc trưng để xem ảnh hưởng. Không dùng Ubuntu: bỏ qua bước này – công cụ trên web (phần B, C) dùng đúng thuật toán và tham số nên ra cùng con số.", "cmd": "cd ~/lab\npython3 congcu/ai_phishing.py --du-lieu dulieu\npython3 congcu/ai_phishing.py --du-lieu dulieu --nguong 0.9\npython3 congcu/ai_phishing.py --du-lieu dulieu --thu thu_ne_tranh.csv\npython3 congcu/ai_phishing.py --du-lieu dulieu --thu thu_ne_tranh.csv --them yeu_cau_nhay_cam"}, {"t": "Kết luận và đề xuất", "w": "all", "d": "Ghi vào phiếu: ngưỡng đề xuất, vì sao thư né tránh lọt, biện pháp ngoài AI, và điều kiện nếu muốn huấn luyện trên thư thật của cơ quan."}], "free": [["f1", "Ngưỡng đề xuất cho CHẶN HẲN và cho GẮN NHÃN CẢNH BÁO – lý do"], ["f2", "Vì sao thư “né tránh” lọt qua? Đề xuất biện pháp ngoài AI"], ["f3", "Nhánh IT: kết quả chạy Python, so sánh với web, thử bỏ/thêm đặc trưng"]], "tool": "aimodel", "qs": [{"id": "q1", "l": "Số thư lừa đảo trong tập huấn luyện", "t": "num", "w": "all", "k": ["6986cd6c33d2498b6366"]}, {"id": "q2", "l": "Số thư lừa đảo trong tập huấn luyện vẫn có SPF = pass", "t": "num", "w": "all", "k": ["e08f1656d7cc9bbc40d4"]}, {"id": "q3", "l": "Đặc trưng có trọng số lớn nhất (mô hình 10 đặc trưng cơ bản)", "t": "sel", "o": ["SPF không đạt", "DKIM không đạt", "Reply-To khác người gửi", "Tên miền na ná", "Liên kết đánh lừa", "Đính kèm nguy hiểm", "Lời lẽ khẩn cấp", "Gửi từ bên ngoài", "Lần đầu liên lạc", "Số liên kết"], "w": "all", "k": ["4d83f02f984c82406100"]}, {"id": "q4", "l": "Tập kiểm tra, ngưỡng 0,50: số thư HỢP LỆ bị chặn nhầm", "t": "num", "w": "all", "k": ["00029ab7529b3f6d4754"]}, {"id": "q5", "l": "Tập kiểm tra, ngưỡng 0,50: số thư LỪA ĐẢO lọt lưới", "t": "num", "w": "all", "k": ["f9ae8c37e80c880a7875"]}, {"id": "q6", "l": "Quy tắc “chặn khi SPF không đạt” trên tập kiểm tra bắt được bao nhiêu thư lừa đảo?", "t": "num", "w": "all", "k": ["a4d8cbdcd30366f7cec4"]}, {"id": "q7", "l": "Khi tăng ngưỡng từ 0,50 lên 0,90 thì", "t": "sel", "o": ["Chặn nhầm ít đi, nhưng để lọt nhiều thư lừa đảo hơn", "Chặn nhầm nhiều hơn và để lọt ít hơn", "Không có gì thay đổi", "Mô hình phải học lại từ đầu"], "w": "all", "k": ["60664facf7b9524aeba1"]}, {"id": "q8", "l": "Tập né tránh, 10 đặc trưng, ngưỡng 0,50: số thư lừa đảo bắt được (trên 40)", "t": "num", "w": "all", "k": ["0b718c55e7f71ed0074e"]}, {"id": "q9", "l": "Thêm đặc trưng “Yêu cầu nhạy cảm”, tập né tránh, ngưỡng 0,50: số thư lừa đảo bắt được", "t": "num", "w": "all", "k": ["abc23dea576c2254e634"]}, {"id": "q10", "l": "Kết luận đúng nhất về bộ lọc thư dùng AI", "t": "sel", "o": ["AI là một lớp bổ sung: vẫn cần xác thực đa yếu tố, văn hoá báo cáo và xác minh qua kênh thứ hai", "Mô hình đạt độ chính xác cao nên có thể thay thế quy trình báo cáo", "Nên chặn mọi thư từ bên ngoài cơ quan", "Chỉ cần kiểm tra SPF là đủ"], "w": "all", "k": ["448984bc8e1eab0a9c3e"]}, {"id": "q11", "l": "Muốn huấn luyện mô hình trên thư thật của cơ quan, trước hết cần", "t": "sel", "o": ["Có căn cứ xử lý dữ liệu cá nhân theo Luật 91/2025/QH15, được phê duyệt, giảm thiểu – ẩn danh dữ liệu và kiểm soát truy cập", "Tải toàn bộ hộp thư lên một dịch vụ AI miễn phí để huấn luyện", "Chỉ cần trưởng phòng CNTT đồng ý bằng lời", "Không cần gì vì là dữ liệu nội bộ"], "w": "all", "k": ["1068aefeb82907367b0d"]}]}, {"id": 8, "buoi": 0, "ext": true, "vm": true, "title": "Phòng lab máy ảo: Kali – pfSense – Suricata (lab dự phòng)", "story": "Phòng học hôm nay cài được máy ảo. Nhóm IT dựng một phòng lab thu nhỏ hoàn toàn cô lập: máy Kali (192.168.56.10) ở vùng LAN, máy web SRV-LAB (192.168.57.20) ở vùng DMZ, tường lửa pfSense nằm giữa. Nhiệm vụ: chứng minh tường lửa cho phép đúng luồng cần thiết và chặn phần còn lại, quét giới hạn qua tường lửa, cho Suricata bắt yêu cầu marker trực tiếp trên dây mạng, rồi hoàn nguyên mọi máy về snapshot.", "asks": ["Quy tắc pfSense có thực sự cho phép đúng một luồng (Kali → web cổng 3000) và chặn phần còn lại không? Bằng chứng ở đâu?", "Quét qua tường lửa khác gì so với bản ghi Nmap quét trong cùng vùng mạng?", "Suricata có bắt được yêu cầu marker trên dây mạng không, ghi những gì vào eve.json?"], "skill": "Dựng phòng lab cô lập có snapshot; viết và kiểm thử quy tắc tường lửa theo thứ tự khớp; quét có giới hạn; kiểm thử tuyến phát hiện bằng marker; hoàn nguyên sau thực hành.", "program": "Lab dự phòng, ngoài lịch 6 buổi: dùng khi phòng học cài được máy ảo (VirtualBox hoặc VMware; máy 16 GB RAM khuyến nghị, tối thiểu 8 GB nếu không cài Wazuh). Làm thật phần thao tác trực tiếp của Buổi 3–4: quét giới hạn, kiểm thử tường lửa ALLOW/DENY, Suricata giám sát trực tiếp, hoàn nguyên snapshot. Thời lượng 90–120 phút. Nếu học viên không cài được, giảng viên trình diễn trên một máy và chiếu lên màn hình.", "vp": "Theo dõi phần trình diễn; đọc ma trận quy tắc tường lửa và giải thích vì sao một kết nối được cho phép hay bị chặn; đọc cảnh báo marker trong eve.json.", "it": "Dựng 3 máy ảo trong 2 mạng nội bộ, cấu hình pfSense, kiểm thử ALLOW/DENY, quét giới hạn qua tường lửa, chạy Suricata giám sát trực tiếp, (tuỳ chọn) đưa eve.json vào Wazuh, hoàn nguyên snapshot.", "sanpham": "Ma trận quy tắc pfSense kèm kết quả kiểm thử ALLOW/DENY; bảng so sánh kết quả Nmap; bản ghi cảnh báo marker (thời điểm, SID, nguồn, đích); xác nhận đã hoàn nguyên snapshot.", "tieuchi": "Chỉ thao tác trong hai mạng nội bộ của phòng lab; có snapshot trước khi làm; chứng minh được cả luồng cho phép và luồng bị chặn; giải thích đúng thứ tự khớp quy tắc; ghi nhận marker đúng SID; hoàn nguyên đầy đủ.", "steps": [{"t": "Dựng phòng lab theo sơ đồ (IT)", "w": "it", "d": "Tạo 3 máy ảo: Kali, pfSense (3 card mạng), SRV-LAB (Ubuntu Server đã chép sẵn thư mục congcu). Gắn card vào các mạng nội bộ ANM-LAN, ANM-DMZ, ANM-WAN – không mạng nào nối ra Internet hay nối với máy thật. Đặt địa chỉ theo bảng trong cẩm nang. Tắt máy rồi tạo snapshot “truoc-lab-8” cho cả 3 máy.", "cmd": "# PowerShell trên Windows (máy ảo đang tắt; VBoxManage nằm trong C:\\Program Files\\Oracle\\VirtualBox)\nVBoxManage modifyvm \"Kali\" --nic1 intnet --intnet1 ANM-LAN\nVBoxManage modifyvm \"pfSense\" --nic1 intnet --intnet1 ANM-WAN --nic2 intnet --intnet2 ANM-LAN --nic3 intnet --intnet3 ANM-DMZ\nVBoxManage modifyvm \"SRV-LAB\" --nic1 intnet --intnet1 ANM-DMZ\nforeach ($m in \"Kali\",\"pfSense\",\"SRV-LAB\") { VBoxManage snapshot $m take truoc-lab-8 }"}, {"t": "Xác nhận cô lập và đường đi (IT)", "w": "it", "d": "Trên Kali: chỉ có địa chỉ 192.168.56.10, cổng mặc định là pfSense 192.168.56.1, không ra được Internet. Trên SRV-LAB: địa chỉ 192.168.57.20, cổng mặc định 192.168.57.1.", "cmd": "# Trên Kali\nip -br addr\nip route\nping -c 2 192.168.56.1\nping -c 2 8.8.8.8          # phải thất bại\n# Trên SRV-LAB\nip -br addr\nip route"}, {"t": "Khởi động dịch vụ trên SRV-LAB (IT)", "w": "it", "d": "Chạy máy web giả lập ở chế độ phòng lab (nghe mọi card mạng của SRV-LAB – chỉ dùng trong mạng nội bộ). Kiểm tra máy đang nghe cổng 22 (SSH) và 3000 (web). Có Juice Shop thì dùng Juice Shop ở cổng 3000.", "cmd": "# Trên SRV-LAB\npython3 ~/lab/congcu/may_web_gia_lap.py --tren-may-ao &\nss -ltn | grep -E \":(22|3000) \""}, {"t": "Quy tắc pfSense và kiểm thử ALLOW/DENY (IT)", "w": "it", "d": "Từ trình duyệt trên Kali mở https://192.168.56.1 (giao diện pfSense). Firewall → Rules → LAN, thêm 2 quy tắc NẰM TRÊN quy tắc “Default allow LAN to any”: (1) Pass TCP nguồn 192.168.56.10 → đích 192.168.57.20 cổng 3000, bật ghi log; (2) Block mọi giao thức nguồn LAN net → đích 192.168.57.0/24, bật ghi log. Apply. Kiểm thử: cổng 3000 phải trả 200 (ALLOW), cổng 22 phải hết thời gian chờ (DENY). Xem Status → System Logs → Firewall. Thử đổi chỗ hai quy tắc rồi kiểm thử lại; xong trả về đúng thứ tự.", "cmd": "# Trên Kali\ncurl -s -o /dev/null -w '%{http_code}\\n' http://192.168.57.20:3000/      # mong đợi 200\nnc -zv -w 3 192.168.57.20 22                                               # mong đợi hết thời gian chờ\nnc -zv -w 3 192.168.57.20 3000                                             # mong đợi succeeded"}, {"t": "Quét giới hạn qua tường lửa (IT)", "w": "it", "d": "Từ Kali quét đúng 4 cổng của một máy. So với bản ghi sẵn nmap_192.168.56.20.txt (quét trong cùng vùng mạng, không qua tường lửa): trạng thái cổng 22 khác thế nào? Dòng MAC Address còn không? Vì sao? Trên SRV-LAB, xem nhật ký máy web giả lập: Nmap để lại dấu vết gì?", "con": {"src": "nmap_192.168.56.20.txt", "view": "raw"}, "cmd": "# Trên Kali (chỉ quét máy này, chỉ 4 cổng)\nnmap -Pn -sV -p 22,80,443,3000 -oA lab8_qua_fw 192.168.57.20\ngrep -E \"^[0-9]+/tcp\" lab8_qua_fw.nmap\n# Trên SRV-LAB\ntail -n 5 ~/lab/ketqua/web_gia_lap_access.log"}, {"t": "Quan sát một GET hợp lệ (IT)", "w": "it", "d": "Từ Kali gửi MỘT yêu cầu GET hợp lệ (curl -v, hoặc ZAP/Burp có sẵn trên Kali). Lưu dòng yêu cầu, tiêu đề, mã trạng thái; làm sạch cookie/token nếu có.", "cmd": "curl -sv \"http://192.168.57.20:3000/rest/products/search?q=apple\" -o /dev/null 2>&1 | grep -E \"^(>|<)\""}, {"t": "Suricata giám sát trực tiếp và marker (IT)", "w": "it", "d": "Trên SRV-LAB: tìm tên card mạng, cho Suricata giám sát card đó với quy tắc marker. Từ Kali gửi yêu cầu marker. Trên SRV-LAB đọc eve.json: cảnh báo SID 1000001 lúc nào, nguồn, đích? So với cảnh báo marker trong bộ dữ liệu (Lab 4).", "cmd": "# Trên SRV-LAB (cửa sổ 1) – thay enp0s3 bằng tên card thật\nip -br link\nmkdir -p ~/ketqua-suricata\nsudo suricata -i enp0s3 -S ~/lab/congcu/marker.rules -l ~/ketqua-suricata\n# Trên Kali\ncurl -s -o /dev/null -w '%{http_code}\\n' http://192.168.57.20:3000/lab-marker-test\n# Trên SRV-LAB (cửa sổ 2)\nsudo jq -c 'select(.event_type==\"alert\") | {timestamp,src_ip,dest_ip,dest_port,sid:.alert.signature_id}' ~/ketqua-suricata/eve.json"}, {"t": "Đưa cảnh báo vào Wazuh (IT, tuỳ chọn)", "w": "it", "d": "Nếu phòng lab có Wazuh (192.168.57.40 hoặc trên SRV-LAB): khai báo eve.json cho agent trên SRV-LAB, khởi động lại agent, gửi lại marker và tìm trên Wazuh sự kiện rule.id 86601 có data.alert.signature_id = 1000001. Nhớ cho pfSense cho phép SRV-LAB gửi tới Wazuh (TCP 1514, 1515).", "cmd": "# /var/ossec/etc/ossec.conf trên SRV-LAB, trong <ossec_config>:\n#   <localfile>\n#     <log_format>json</log_format>\n#     <location>/home/USER/ketqua-suricata/eve.json</location>\n#   </localfile>\nsudo systemctl restart wazuh-agent"}, {"t": "Hoàn nguyên snapshot (IT)", "w": "it", "d": "Dừng máy web giả lập và Suricata, tắt 3 máy ảo, hoàn nguyên snapshot “truoc-lab-8”, bật lại và kiểm tra quy tắc pfSense đã trở về như trước. Ghi kết quả vào phiếu.", "cmd": "# PowerShell trên Windows (máy ảo đang tắt)\nforeach ($m in \"Kali\",\"pfSense\",\"SRV-LAB\") { VBoxManage snapshot $m restore truoc-lab-8 }\nVBoxManage snapshot \"pfSense\" list"}], "free": [["f1", "Ma trận quy tắc pfSense (thứ tự – nguồn – đích – cổng – hành động – lý do) và kết quả kiểm thử ALLOW/DENY"], ["f2", "So sánh Nmap: bản ghi sẵn (cùng mạng) và bản quét qua pfSense – khác gì, vì sao"], ["f3", "Cảnh báo marker trên dây mạng: thời điểm, SID, nguồn, đích; (tuỳ chọn) sự kiện tương ứng trên Wazuh"], ["f4", "Kết quả hoàn nguyên snapshot và kiểm tra lại"]], "tool": null, "qs": [{"id": "q1", "l": "Sau khi áp quy tắc, từ Kali chỉ còn cổng nào của 192.168.57.20 trả lời?", "t": "num", "w": "it", "k": ["99a2284c0ca9386071b1"]}, {"id": "q2", "l": "Nmap từ Kali (qua pfSense) thấy cổng 22 của máy web ở trạng thái", "t": "sel", "o": ["open", "closed", "filtered"], "w": "it", "k": ["321472d16189f3d8f78f"]}, {"id": "q3", "l": "Đưa quy tắc Block lên TRÊN quy tắc Pass cổng 3000 thì", "t": "sel", "o": ["Cổng 3000 cũng bị chặn, vì pfSense áp dụng quy tắc khớp đầu tiên tính từ trên xuống", "Không thay đổi gì, vì quy tắc Pass luôn được ưu tiên", "Mọi cổng đều được mở", "pfSense báo lỗi và không cho lưu"], "w": "all", "k": ["680788bb9d2b7524c452"]}, {"id": "q4", "l": "SID của cảnh báo marker mà Suricata ghi vào eve.json", "t": "num", "w": "all", "k": ["87f4012ba8adaadc03da"]}, {"id": "q5", "l": "Vì sao bản ghi sẵn nmap_192.168.56.20.txt có dòng MAC Address còn bản quét qua pfSense thì không?", "t": "sel", "o": ["Bản ghi sẵn quét trong cùng một mạng; quét qua pfSense là đi qua bộ định tuyến nên không thấy địa chỉ MAC của máy đích", "pfSense xoá địa chỉ MAC để che giấu máy web", "Nmap trên Kali bị lỗi", "Máy web giả lập không có card mạng"], "w": "it", "k": ["ee37b8bda9435c39aafc"]}, {"id": "q6", "l": "Trước khi quét trên phòng lab máy ảo, bắt buộc phải", "t": "sel", "o": ["Xác nhận phạm vi được phép (chỉ hai mạng nội bộ của phòng lab) và tạo snapshot", "Mở Internet cho Kali để cập nhật công cụ", "Quét thử dải mạng của cơ quan để so sánh", "Tắt tường lửa cho nhanh"], "w": "all", "k": ["99683ea79da76bde0ca9"]}]}];
window.LAB_EVID=[{"id": "E1", "t": "Quy chế bảo đảm an toàn thông tin của cơ quan", "d": "Ban hành 03/2024. Căn cứ: Luật An toàn thông tin mạng 86/2015/QH13; Nghị định 85/2016/NĐ-CP.", "k": "c228de80646b0d0de112"}, {"id": "E2", "t": "Quyết định phê duyệt cấp độ 3 cho hệ thống (09/2023)", "d": "Phê duyệt theo Nghị định 85/2016/NĐ-CP.", "k": "21cfaa5c63996dfe4c79"}, {"id": "E3", "t": "Hợp đồng bảo trì với nhà thầu", "d": "Hiệu lực 01/07/2025 – 30/06/2026. Phụ lục: nhà thầu truy cập qua VPN từ 198.51.100.200.", "k": "3926fd311085f93186d9"}, {"id": "E4", "t": "Bảng phân quyền người dùng (cập nhật 15/09/2026)", "d": "30 tài khoản, có vu.ngoc.lan (Văn thư).", "k": "facc0edd604295859aaa"}, {"id": "E5", "t": "Cấu hình lưu nhật ký tập trung", "d": "Wazuh lưu 90 ngày; 5 máy chủ gửi log.", "k": "bcf30c7eef0944c9e281"}, {"id": "E6", "t": "Văn bản phân công bộ phận/nhân sự bảo vệ dữ liệu cá nhân", "d": "Chưa có.", "k": "df8de427c207416809f3"}, {"id": "E7", "t": "Nhật ký sao lưu", "d": "Job sao lưu hằng đêm thành công 30/30 ngày. Chưa có biên bản thử khôi phục.", "k": "08a1d15d5279a3ca8b9a"}, {"id": "E8", "t": "Đánh giá tác động xử lý dữ liệu cá nhân", "d": "Chưa lập.", "k": "9d8fd393df2990b20f90"}, {"id": "E9", "t": "Nhật ký truy cập của ứng dụng văn bản", "d": "Ghi người dùng, thời gian, hành động; lưu trong CSDL và gửi về Wazuh.", "k": "8185ee60bacb46a179c7"}, {"id": "E10", "t": "Sơ đồ mạng hiện trạng (10/2026)", "d": "Có chữ ký trưởng phòng CNTT.", "k": "9772d7757c42803d44b4"}];
